mapper.select:
select  count(1)task_count,task_type from wms_tasks t
where 1=1

    and DATE(t.create_time) = #{createTimeString}


    and t.task_status = #{taskStatus}



    and t.target_warehouse_id = #{targetWarehouseId}



    and t.source_warehouse_id = #{sourceWarehouseId}


group by  t.task_type

select DATE_FORMAT(t.create_time, '%Y-%m') as name, count(1) as `value`
from wms_stock_in_orders t
where YEAR(t.create_time) = #{year}

    and t.warehouse_id = #{warehouseId}

group by DATE_FORMAT(t.create_time, '%Y-%m')
order by name asc

select DATE_FORMAT(t.create_time, '%Y-%m') as name, count(1) as `value`
from wms_out_orders t
where YEAR(t.create_time) = #{year}

    and t.warehouse_id = #{warehouseId}

group by DATE_FORMAT(t.create_time, '%Y-%m')
order by name asc
